input.command:
cd /tmp/crit8
run(){ O=$(mktemp); E=$(mktemp); /workspace/dataset/test8_executable --domain a.com --mode both "$1" >"$O" 2>"$E"; RC=$?; 
 if [ $RC -eq 0 ] && head -1 "$O"|grep -q '^usage:'; then R="HELP(rc=0)"; elif [ $RC -eq 0 ]; then R="RAN(rc=0): $(head -1 "$O")"; else R="rc=$RC :: $(tail -1 "$E")"; fi
 printf '%-12s -> %s\n' "$1" "$R"; rm -f "$O" "$E"; }
for t in "-h" "-h=" "-h=x" "-h-" "-h--" "-hx" "-hxy" "-hx=y" "-hh" "-hhh" "-hh=x" "-hh=" "-h=h" "-hh-" "-hxh=y" "-hhx=y" "-h==x" "-h=-x" "-hh=-x" "-ha=b" "-hah=b"; do run "$t"; done

cd /tmp/crit8
rp(){ CP="$1"; V=$(node -e "process.stdout.write('X'+String.fromCodePoint($CP)+'Y')"); O=$(mktemp); E=$(mktemp);
 /workspace/dataset/test8_executable --domain a.com --mode "$V" >"$O" 2>"$E"; 
 printf 'U+%-6s -> %s\n' "$(printf '%04X' $CP)" "$(tail -1 "$E" | sed 's/^.*invalid choice: //; s/ (choose.*//')"; rm -f "$O" "$E"; }
for cp in 0x01 0x08 0x09 0x0a 0x0b 0x0c 0x0d 0x1b 0x1f 0x7f 0x80 0x85 0x9f 0xa0 0xad 0xe9 0x0301 0x0378 0x200b 0x200c 0x2028 0x2029 0x3000 0x31ef 0x31ee 0xe000 0xfff9 0xfffe 0x1f600 0x10400 0x105c0 0x11bc0 0x1e5d0 0x2ebf0 0x10fffe 0x10ffff 0x2ffc 0x2ffb; do rp $cp; done
